#include <iostream>

int main() {
    const int stock = 0;
    std::cout << (stock > 0 ? "in stock" : "sold out") << '\n';

    const int total = 42;
    const int shipping = total >= 50 ? 0 : 5;
    std::cout << "shipping: " << shipping << '\n';

    const int x = 0;
    const char sign = x > 0 ? '+' : (x < 0 ? '-' : '0');
    std::cout << "sign: " << sign << '\n';

    const int uploadCount = 1;
    const int downloadCount = 4;
    std::cout << uploadCount << ' ' << (uploadCount == 1 ? "file" : "files") << '\n';
    std::cout << downloadCount << ' ' << (downloadCount == 1 ? "file" : "files") << '\n';
    return 0;
}
